  'Add {0}': '{0} ઉમેરો',
  'Adding…': 'ઉમેરી રહ્યું છે...',
  Address: 'સરનામું',
  'Address line 1': 'એડ્રેસ લાઇન 1',
  'Address line 2': 'એડ્રેસ લાઇન 2',
  'Address of': 'નું સરનામું',
  'Address:': 'સરનામું:',
  'Adds a tiny invisible image to each email you send. When the reader\'s mail program loads it, the message shows "opened" in the inbox and counts toward the campaign\'s read rate. It is a hint, not proof: some programs block images (so a read email shows nothing), and some load them in advance (so an unread one shows as opened).':
    'તમે મોકલો છો તે દરેક ઇમેઇલમાં એક નાની અદ્રશ્ય છબી ઉમેરે છે. જ્યારે રીડરનો મેઇલ પ્રોગ્રામ તેને લોડ કરે છે, ત્યારે સંદેશ ઇનબોક્સમાં "ખોલો" બતાવે છે અને ઝુંબેશના વાંચન દરમાં ગણાય છે. તે સંકેત છે, સાબિતી નથી: કેટલાક પ્રોગ્રામ ઈમેજીસને અવરોધિત કરે છે (જેથી વાંચેલા ઈમેઈલ કંઈ દેખાતું નથી), અને કેટલાક તેને અગાઉથી લોડ કરે છે (જેથી ન વાંચેલ ઈમેઈલ ખુલે તેમ બતાવે છે).',
  "Adds industrial templates this number doesn't have yet (such as quotation_ready, which carries a quotation PDF) as drafts":
    'ઔદ્યોગિક નમૂનાઓ ઉમેરે છે જે આ નંબર પાસે હજુ સુધી નથી (જેમ કે ક્વોટેશન_રેડી, જેમાં અવતરણ PDF હોય છે) ડ્રાફ્ટ તરીકે',
  Adjust: 'એડજસ્ટ કરો',
