  'Agencies and distributors sell AutoReach under their own brand and domain.':
    'એજન્સીઓ અને વિતરકો તેમની પોતાની બ્રાન્ડ અને ડોમેન હેઠળ AutoReach વેચે છે.',
  'Agencies and distributors who sell AutoReach under their own brand: their branding and domain, the client workspaces they manage, the commission they earn and the payouts they request.':
    'એજન્સીઓ અને વિતરકો કે જેઓ તેમની પોતાની બ્રાન્ડ હેઠળ AutoReach વેચે છે: તેમનું બ્રાંડિંગ અને ડોમેન, તેઓ જે ક્લાયન્ટ વર્કસ્પેસ મેનેજ કરે છે, તેઓ જે કમિશન કમાય છે અને તેઓ જે ચૂકવણીની વિનંતી કરે છે.',
