  'Answer incoming calls from the call bar that appears near the bottom of the screen.':
    'સ્ક્રીનના તળિયે દેખાતા કોલ બારમાંથી ઇનકમિંગ કોલ્સનો જવાબ આપો.',
  'Answer is': 'જવાબ છે',
