  'Answer saved': 'જવાબ સાચવ્યો',
  Answered: 'જવાબ આપ્યો',
  Answers: 'જવાબો',
  'Answers come from your own knowledge base.': 'જવાબો તમારા પોતાના જ્ઞાન આધાર પરથી આવે છે.',
  'Answers from your own articles inside the reply window, and hands over to a person when unsure.':
    'જવાબ વિંડોની અંદર તમારા પોતાના લેખોમાંથી જવાબો, અને જ્યારે અચોક્કસ હોય ત્યારે વ્યક્તિને સોંપો.',
  "Answers inbound WhatsApp messages from your knowledge base, inside the 24-hour service window, and hands the conversation to a person whenever it isn't sure. Test it in 'Try a question' before switching it on.":
    "24-કલાકની સેવા વિન્ડોની અંદર, તમારા જ્ઞાન આધારમાંથી ઇનબાઉન્ડ WhatsApp સંદેશાઓનો જવાબ આપે છે અને જ્યારે પણ કોઈ વ્યક્તિ ખાતરી ન હોય ત્યારે વાતચીતને સોંપે છે. તેને ચાલુ કરતા પહેલા 'પ્રશ્નનો પ્રયાસ કરો'માં તેનું પરીક્ષણ કરો.",
  'Answers price questions and counter-offers instantly, within limits you set.':
    'તમે સેટ કરેલી મર્યાદામાં, કિંમતના પ્રશ્નો અને કાઉન્ટર-ઓફરનો તરત જ જવાબ આપો.',
  'Answers to the question sent when a conversation is resolved, by the channels each team owns. CSAT is the share of “Good”.':
    'દરેક ટીમની માલિકીની ચેનલો દ્વારા જ્યારે વાતચીત ઉકેલાઈ જાય ત્યારે મોકલવામાં આવેલા પ્રશ્નના જવાબો. CSAT એ “ગુડ” નો હિસ્સો છે.',
