  'AutoReach branding hidden': 'AutoReach બ્રાન્ડિંગ છુપાયેલ છે',
  'Automate follow-ups and capture structured enquiries.':
    'ફોલો-અપ્સને સ્વચાલિત કરો અને માળખાગત પૂછપરછો મેળવો.',
  "Automatic answers to customers who write in. The welcome goes to someone's first message. The away reply goes outside your business hours and on holidays, at most once per customer per wait period. During an out-of-office period that message is sent instead. Nothing is sent to a conversation an agent has taken, to button taps, or to STOP.":
    'લખનારા ગ્રાહકોને આપોઆપ જવાબો. સ્વાગત કોઈના પ્રથમ સંદેશ પર જાય છે. દૂર જવાબ તમારા કામકાજના કલાકોની બહાર અને રજાઓના દિવસે, પ્રતિ ગ્રાહક દીઠ પ્રતિક્ષા અવધિમાં વધુમાં વધુ એકવાર જાય છે. ઑફિસની બહારના સમયગાળા દરમિયાન તે સંદેશ તેના બદલે મોકલવામાં આવે છે. એજન્ટે લીધેલી વાતચીતમાં, બટન ટેપ પર અથવા સ્ટોપ પર કંઈપણ મોકલવામાં આવતું નથી.',
  'Automatic sync uploads visits as soon as your device reconnects.':
    'તમારું ઉપકરણ ફરીથી કનેક્ટ થતાંની સાથે જ સ્વચાલિત સમન્વયન અપલોડ મુલાકાતો.',
