  'Both paths carry on with the steps below': 'બંને પાથ નીચેના પગલાઓ સાથે આગળ વધે છે',
  'Both records have one, so the stricter setting wins — {0}.':
    'બંને રેકોર્ડમાં એક છે, તેથી કડક સેટિંગ જીતે છે — {0}.',
  'Both records have one; nothing changes — {0}.': 'બંને રેકોર્ડ એક છે; કંઈ બદલાતું નથી — {0}.',
