  'Branch on whether they respond': 'તેઓ જવાબ આપે છે કે કેમ તેના પર શાખા',
  'Branches (If…, Wait for a reply) let one automation treat each customer differently.':
    'શાખાઓ (જો…, જવાબ માટે રાહ જુઓ) એક ઓટોમેશન દરેક ગ્રાહકને અલગ રીતે વર્તે છે.',
