  'Breach log': 'ભંગ લોગ',
  Breakdown: 'ભંગાણ',
  'Bring in your customers': 'તમારા ગ્રાહકોને લાવો',
  Browser: 'બ્રાઉઝર',
  'Browser notifications': 'બ્રાઉઝર સૂચનાઓ',
  'Browser notifications are switched off on this server.': 'આ સર્વર પર બ્રાઉઝર સૂચનાઓ બંધ છે.',
  'Budget band': 'બજેટ બેન્ડ',
  'Budget-Constrained SME (Limited quarterly funds)': 'બજેટ-અવરોધિત SME (મર્યાદિત ત્રિમાસિક ભંડોળ)',
  'Build a form, put it on your website as a link or an embedded frame, and every submission makes or finds the contact, records what they agreed to, and opens an enquiry in your pipeline. It works alongside WhatsApp Flows and the chat widget.':
    'એક ફોર્મ બનાવો, તેને તમારી વેબસાઇટ પર લિંક અથવા એમ્બેડેડ ફ્રેમ તરીકે મૂકો, અને દરેક સબમિશન સંપર્ક બનાવે છે અથવા શોધે છે, તેઓ શું સંમત થયા હતા તે રેકોર્ડ કરે છે અને તમારી પાઇપલાઇનમાં પૂછપરછ ખોલે છે. તે WhatsApp ફ્લો અને ચેટ વિજેટની સાથે કામ કરે છે.',
  'Build an in-chat form screen by screen — add fields, mark which are required, and the WhatsApp Flow JSON is generated for you. No hand-written JSON needed.':
    'સ્ક્રીન દ્વારા ઇન-ચેટ ફોર્મ સ્ક્રીન બનાવો — ફીલ્ડ્સ ઉમેરો, જે જરૂરી છે તેને ચિહ્નિત કરો અને તમારા માટે WhatsApp ફ્લો JSON જનરેટ કરવામાં આવ્યો છે. હાથથી લખાયેલ JSON ની જરૂર નથી.',
  'Build it from the products you already quote.':
    'તમે પહેલેથી જ ક્વોટ કરેલા ઉત્પાદનોમાંથી તેને બનાવો.',
  "Build the automation as a list of steps, or on the canvas as boxes and arrows. On the canvas, drag a step to move it, drag from a dot on its bottom edge to another step to join them, and drag new steps in from the palette. 'If…' and 'Wait for a reply' have two ways out; a way out with nothing joined ends the journey there. Loops are not allowed.":
    "ઓટોમેશનને પગલાઓની સૂચિ તરીકે અથવા કેનવાસ પર બોક્સ અને તીરો તરીકે બનાવો. કેનવાસ પર, તેને ખસેડવા માટે એક પગથિયું ખેંચો, તેની નીચેની કિનારી પરના બિંદુથી તેમાં જોડાવા માટે બીજા સ્ટેપ પર ખેંચો અને પેલેટમાંથી નવા સ્ટેપ્સને અંદર ખેંચો. 'જો…' અને 'જવાબની રાહ જુઓ' પાસે બે રસ્તા છે; કંઈપણ જોડાયા વિના બહાર નીકળવાનો માર્ગ ત્યાંની યાત્રાને સમાપ્ત કરે છે. લૂપ્સની મંજૂરી નથી.",
  'Build the menu here instead of in Exotel’s dashboard.':
    'Exotel ના ડેશબોર્ડને બદલે અહીં મેનૂ બનાવો.',
  'Build the steps in the builder.': 'બિલ્ડરમાં પગલાઓ બનાવો.',
