    'વોટ્સએપ પર કૉલ કરો (ગ્રાહકે કૉલ કરવાની મંજૂરી આપી હોવી જોઈએ)',
  'Call opt-in': 'કૉલ ઑપ્ટ-ઇન',
  'Call outcomes are kept on the deal’s history.':
    'કૉલના પરિણામો સોદાના ઇતિહાસ પર રાખવામાં આવે છે.',
  'Call phone number': 'ફોન નંબર પર કૉલ કરો',
  'Call {0}': '{0} ને કૉલ કરો',
  'Caller presses': 'કૉલર પ્રેસ કરે છે',
  "Caller's": 'કોલરના',
  "Callers hear the menu and press a key. An option can ring a team, open a sub-menu (for example Sales, Purchase and Service, with Repairs, Spares and Ticket status under Service), or read out a ticket's or order's status the caller keys in, then ring a team.":
    'કૉલર મેનૂ સાંભળે છે અને કી દબાવો. એક વિકલ્પ ટીમને રિંગ કરી શકે છે, સબ-મેનૂ ખોલી શકે છે (ઉદાહરણ તરીકે વેચાણ, ખરીદી અને સેવા, સમારકામ, સ્પેર્સ અને સેવા હેઠળ ટિકિટની સ્થિતિ સાથે), અથવા કૉલર કીઝમાં ટિકિટ અથવા ઓર્ડરની સ્થિતિ વાંચી શકે છે, પછી ટીમને રિંગ કરી શકે છે.',
  "Callers hear the menu and press a key; the call then rings only that option's team, for example “For English, press 1. हिंदी के लिए दो दबाइए।”":
    'કૉલર મેનૂ સાંભળે છે અને કી દબાવો; કૉલ પછી ફક્ત તે વિકલ્પની ટીમની રિંગ વાગે છે, ઉદાહરણ તરીકે “અંગ્રેજી માટે, 1 દબાવો. हिंदी के लिए दो दबाइए।”',
  "Callers hear your prompt and press a key; the call then rings only that option's team. Say every option in the prompt, for example “Press 1 for English; press 2 for Hindi.”":
    'કૉલર તમારો પ્રોમ્પ્ટ સાંભળે છે અને કી દબાવો; કોલ પછી માત્ર તે વિકલ્પની ટીમની રીંગ વાગે છે. પ્રોમ્પ્ટમાં દરેક વિકલ્પ કહો, ઉદાહરણ તરીકે "અંગ્રેજી માટે 1 દબાવો; હિન્દી માટે 2 દબાવો."',
  'Callers hear:': 'કૉલર્સ સાંભળે છે:',
  'Callers pressing “{0}” will no longer be routed by it.':
    '"{0}" દબાવતા કૉલર્સ હવે તેના દ્વારા રૂટ કરવામાં આવશે નહીં.',
  'Callers reach the right team through a phone menu.':
    'કૉલર ફોન મેનૂ દ્વારા યોગ્ય ટીમ સુધી પહોંચે છે.',
  'Calling is not set up yet ({0}). An administrator connects the Exotel account under Channels.':
    'કૉલિંગ હજી સેટ અપ થયું નથી ({0}). એક એડમિનિસ્ટ્રેટર ચેનલ્સ હેઠળ Exotel એકાઉન્ટને જોડે છે.',
  'Calling {0} from the in-browser phone. Watch the phone bar in the corner.':
    'ઇન-બ્રાઉઝર ફોનથી {0} ને કૉલ કરી રહ્યાં છીએ. ખૂણામાં ફોન બાર જુઓ.',
  'Calling {0}…': '{0} ને કૉલ કરી રહ્યાં છીએ…',
  'Calling…': 'કૉલ કરી રહ્યાં છીએ…',
  'Calls could not be loaded.': 'કૉલ્સ લોડ કરી શકાયા નથી.',
  'Calls customers made to your WhatsApp number and calls your team made to customers who allowed it. When recording is on, the browser on the call records both sides and saves it when the call ends; tell customers that calls are recorded.':
    'તમારા WhatsApp નંબર પર બનાવેલા ગ્રાહકોને કૉલ કરે છે અને તમારી ટીમ બનાવેલા ગ્રાહકોને કૉલ કરે છે જેમણે તેને મંજૂરી આપી હતી. જ્યારે રેકોર્ડિંગ ચાલુ હોય, ત્યારે કૉલ પરનું બ્રાઉઝર બંને બાજુએ રેકોર્ડ કરે છે અને કૉલ સમાપ્ત થાય ત્યારે તેને સાચવે છે; ગ્રાહકોને જણાવો કે કોલ્સ રેકોર્ડ થયેલ છે.',
  'Calls from your own phone can be written up too, so the record is complete.':
    'તમારા પોતાના ફોનમાંથી કૉલ પણ લખી શકાય છે, જેથી રેકોર્ડ પૂર્ણ થાય.',
  'Calls ring every agent until this is fixed:':
    'જ્યાં સુધી આ નિશ્ચિત ન થાય ત્યાં સુધી દરેક એજન્ટને કૉલ કરો:',
