  'Capacity (Hrs)': 'ક્ષમતા (કલાક)',
  'Captcha script failed to load': 'કેપ્ચા સ્ક્રિપ્ટ લોડ કરવામાં નિષ્ફળ',
  'Capture enquiries from your website straight into the pipeline.':
    'તમારી વેબસાઇટ પરથી સીધી પાઇપલાઇનમાં પૂછપરછ કેપ્ચર કરો.',
  'Capture leads from your website': 'તમારી વેબસાઇટ પરથી લીડ્સ કેપ્ચર કરો',
  'Captures the customer PO, delivery terms and line items in one place.':
    'ગ્રાહક પીઓ, ડિલિવરી શરતો અને લાઇન આઇટમ્સને એક જગ્યાએ કેપ્ચર કરે છે.',
  Card: 'કાર્ડ',
