  'Catalogue · MNI Assist': 'કેટલોગ · MNI આસિસ્ટ',
  'Catalogue:': 'કેટલોગ:',
  'Catches the issues Meta most often rejects before you submit, so approval is faster.':
    'તમે સબમિટ કરો તે પહેલાં મેટા મોટાભાગે નકારી કાઢે છે તે મુદ્દાઓને પકડે છે, તેથી મંજૂરી ઝડપી છે.',
  Category: 'શ્રેણી',
  Cement: 'સિમેન્ટ',
  'Central Europe': 'મધ્ય યુરોપ',
  'Central Tax (CGST):': 'સેન્ટ્રલ ટેક્સ (CGST):',
  'Central Tax CGST (₹)': 'સેન્ટ્રલ ટેક્સ CGST (₹)',
  "Chains of steps that run themselves once a trigger fires. New automations start paused — turn one on once you've tested it with Dry-run.":
    'પગલાંઓની સાંકળો કે જે એકવાર ટ્રિગર ફાયર થઈ જાય તે પછી પોતાને ચલાવે છે. નવા ઓટોમેશન થોભાવવામાં આવે છે - એકવાર તમે ડ્રાય-રન સાથે તેનું પરીક્ષણ કરી લો તે પછી એક ચાલુ કરો.',
  Challan: 'ચલણ',
  'Challan #': 'ચલણ #',
  'Challan Ref: {0} | PO: {1}': 'ચલણ સંદર્ભ: {0} | PO: {1}',
  'Challan: {0}': 'ચલણ: {0}',
  Chance: 'તક',
  'Chance of winning a deal in each stage, as a percentage. Expected weights each open deal by its stage. A later stage cannot be lower than an earlier one.':
    'ટકાવારી તરીકે દરેક તબક્કામાં સોદો જીતવાની તક. દરેક ઓપન ડીલ તેના સ્ટેજ દ્વારા અપેક્ષિત વજન. પછીનો તબક્કો પહેલા કરતા ઓછો હોઈ શકતો નથી.',
  'Chance of winning at': 'ખાતે જીતવાની તક',
  'Chances for': 'માટે તકો',
  'Change (e.g. -2 for damaged, 3 for found)': 'બદલો (દા.ત. ક્ષતિગ્રસ્ત માટે -2, મળેલા માટે 3)',
  'Change PIN': 'પિન બદલો',
  'Change domain': 'ડોમેન બદલો',
  'Change password': 'પાસવર્ડ બદલો',
  'Change plan': 'યોજના બદલો',
  'Change the display name and click Submit for review.':
    'પ્રદર્શન નામ બદલો અને સમીક્ષા માટે સબમિટ કરો ક્લિક કરો.',
  'Change the requested name': 'વિનંતી કરેલ નામ બદલો',
  'Change tier': 'સ્તર બદલો',
  "Change what the platform's own emails say. The variables listed under each email, such as the workspace name, are filled in when it is sent. Keep the html.escape filter on anything a person typed, such as names. Restore default puts the original wording back.":
    'પ્લેટફોર્મના પોતાના ઇમેઇલ્સ શું કહે છે તે બદલો. દરેક ઈમેલ હેઠળ સૂચિબદ્ધ વેરિયેબલ્સ, જેમ કે વર્કસ્પેસ નામ, જ્યારે તે મોકલવામાં આવે ત્યારે ભરવામાં આવે છે. html.escape ફિલ્ટરને વ્યક્તિએ ટાઈપ કરેલી કોઈપણ વસ્તુ પર રાખો, જેમ કે નામ. રિસ્ટોર ડિફૉલ્ટ મૂળ શબ્દોને પાછું મૂકે છે.',
  'Change your password at any time.': 'કોઈપણ સમયે તમારો પાસવર્ડ બદલો.',
