  'Company accounts': 'કંપની એકાઉન્ટ્સ',
  "Company accounts go in as customers when they are created or edited, and a quotation marked won goes in once as a sales order — net of GST, which the ERP applies from its own tax setup. Invoices and each customer's outstanding balance are read back every six hours and shown on the account. Anything the ERP refuses is retried on the next pass.":
    'જ્યારે કંપનીના ખાતાઓ બનાવવામાં આવે અથવા સંપાદિત કરવામાં આવે ત્યારે ગ્રાહકો તરીકે જાય છે અને જીત ચિહ્નિત થયેલ અવતરણ એક જ વાર વેચાણ ઓર્ડર તરીકે જાય છે - GSTની ચોખ્ખી, જે ERP તેના પોતાના ટેક્સ સેટઅપથી લાગુ થાય છે. ઇન્વૉઇસેસ અને દરેક ગ્રાહકનું બાકી બેલેન્સ દર છ કલાકે પાછા વાંચવામાં આવે છે અને એકાઉન્ટ પર બતાવવામાં આવે છે. ERP જે કંઈપણ ઇનકાર કરે છે તે પછીના પાસ પર ફરીથી પ્રયાસ કરવામાં આવે છે.',
  'Company name': 'કંપનીનું નામ',
  Compare: 'સરખામણી કરો',
  'Compare Expected, Commit and Best case to plan with confidence.':
    'આત્મવિશ્વાસ સાથે યોજના બનાવવા માટે અપેક્ષિત, પ્રતિબદ્ધ અને શ્રેષ્ઠ કેસની તુલના કરો.',
