  'Connect Gmail': 'Gmail ને કનેક્ટ કરો',
  'Connect Microsoft 365': 'Microsoft 365 ને કનેક્ટ કરો',
  'Connect WhatsApp number': 'વોટ્સએપ નંબર જોડો',
  'Connect a Facebook Page': 'ફેસબુક પેજને કનેક્ટ કરો',
  'Connect a Facebook Page, sign in with someone who is an admin of the Page, and allow every permission asked for.':
    'ફેસબુક પેજને કનેક્ટ કરો, પેજના એડમિન હોય તેવી વ્યક્તિ સાથે સાઇન ઇન કરો અને માંગવામાં આવેલી દરેક પરવાનગીને મંજૂરી આપો.',
  'Connect a WhatsApp number': 'WhatsApp નંબર જોડો',
  'Connect a channel before creating a template.': 'ટેમ્પલેટ બનાવતા પહેલા ચેનલને કનેક્ટ કરો.',
  'Connect a channel before saving a template.': 'ટેમ્પલેટ સાચવતા પહેલા ચેનલને કનેક્ટ કરો.',
  'Connect a channel to build its catalogue.': 'તેની સૂચિ બનાવવા માટે ચેનલને કનેક્ટ કરો.',
  'Connect a number': 'નંબર જોડો',
  'Connect a number that is already registered with Meta Cloud API. Your number and security PIN stay unchanged.':
    'મેટા ક્લાઉડ API સાથે પહેલેથી જ નોંધાયેલ નંબરને કનેક્ટ કરો. તમારો નંબર અને સુરક્ષા પિન યથાવત રહેશે.',
  'Connect again': 'ફરીથી કનેક્ટ કરો',
  'Connect an ad account': 'જાહેરાત એકાઉન્ટ કનેક્ટ કરો',
  'Connect existing number': 'હાલના નંબરને કનેક્ટ કરો',
  'Connect mailbox': 'મેઇલબોક્સને કનેક્ટ કરો',
  'Connect new numbers in a guided flow.': 'માર્ગદર્શિત પ્રવાહમાં નવા નંબરોને જોડો.',
  'Connect number': 'કનેક્ટ નંબર',
  'Connect the Facebook Page your lead ads run on. Every form submission becomes a contact and an enquiry.':
    'તમારી લીડ જાહેરાતો જે ફેસબુક પેજ પર ચાલે છે તેને કનેક્ટ કરો. દરેક ફોર્મ સબમિશન એક સંપર્ક અને પૂછપરછ બની જાય છે.',
  "Connect the mailbox your customers' replies arrive in, and their replies are added to the conversation in your inbox. Only mail from your contacts is added, and only mail that arrives after you connect. A failed-delivery notice for an address that does not exist also stops further email to that contact. Nothing in the mailbox is changed, moved or deleted.":
    'તમારા ગ્રાહકોના જવાબો આવે છે તે મેઇલબોક્સને કનેક્ટ કરો અને તેમના જવાબો તમારા ઇનબોક્સમાંની વાતચીતમાં ઉમેરવામાં આવે છે. તમારા સંપર્કોમાંથી ફક્ત મેઇલ ઉમેરવામાં આવે છે, અને ફક્ત તે જ મેઇલ જે તમે કનેક્ટ થયા પછી આવે છે. જે સરનામું અસ્તિત્વમાં નથી તેના માટે નિષ્ફળ-ડિલિવરી નોટિસ પણ તે સંપર્કને વધુ ઇમેઇલ અટકાવે છે. મેઈલબોક્સમાં કંઈપણ બદલાયું, ખસેડવામાં અથવા કાઢી નાખવામાં આવ્યું નથી.',
  'Connect to Exotel': 'Exotel સાથે કનેક્ટ કરો',
  'Connect your ERP (Tally, Zoho Books…) under Integrations to add what customers owe: ageing, days sales outstanding and the customers to chase first.':
    'ગ્રાહકોને શું બાકી છે તે ઉમેરવા માટે તમારા ERP (Tally, Zoho Books…) ને એકીકરણ હેઠળ કનેક્ટ કરો: વૃદ્ધાવસ્થા, વેચાણ બાકી રહે છે અને ગ્રાહકો પ્રથમ પીછો કરે છે.',
  'Connect your Meta ad account and each ad shows what it cost, per chat or lead and per enquiry.':
    'તમારા મેટા એડ એકાઉન્ટને કનેક્ટ કરો અને દરેક જાહેરાત બતાવે છે કે તેની કિંમત, ચેટ અથવા લીડ દીઠ અને પૂછપરછ દીઠ છે.',
