  "Define what each role can see and do across the workspace. Expand a role to inspect and edit its permissions. Changing a role's permissions applies immediately to everyone holding it.":
    'દરેક ભૂમિકા સમગ્ર વર્કસ્પેસમાં શું જોઈ શકે છે અને શું કરી શકે છે તે વ્યાખ્યાયિત કરો. તેની પરવાનગીઓનું નિરીક્ષણ કરવા અને સંપાદિત કરવા માટે ભૂમિકાને વિસ્તૃત કરો. ભૂમિકાની પરવાનગીઓ બદલવી તે ધરાવનાર દરેકને તરત જ લાગુ પડે છે.',
