  ERROR: 'ભૂલ',
  'Each AMC renewal lost': 'દરેક AMC નવીકરણ ખોવાઈ ગયું',
  'Each AMC renewal won': 'દરેક AMC નવીકરણ જીત્યું',
  'Each Meta ad or boosted post that opened a chat or brought a lead-form lead, with the enquiries and wins that followed. Connect your ad account to see what each ad cost, and what each enquiry cost.':
    'દરેક મેટા જાહેરાત અથવા બૂસ્ટ કરેલી પોસ્ટ કે જેણે ચેટ ખોલી અથવા લીડ-ફોર્મ લીડ લાવી, જેમાં પૂછપરછ અને તે પછીની જીત છે. દરેક જાહેરાતની કિંમત કેટલી છે અને દરેક પૂછપરછની કિંમત કેટલી છે તે જોવા માટે તમારું એડ એકાઉન્ટ કનેક્ટ કરો.',
  'Each campaign from send to sale: replies, enquiries, value won and cost per enquiry.':
    'મોકલવાથી લઈને વેચાણ સુધીની દરેક ઝુંબેશ: જવાબો, પૂછપરછ, મૂલ્ય જીત્યું અને પૂછપરછ દીઠ ખર્ચ.',
  'Each contact needs a WhatsApp-capable phone number. Numbers without a country code get the default one you choose next.':
    'દરેક સંપર્કને WhatsApp-સક્ષમ ફોન નંબરની જરૂર છે. દેશના કોડ વિનાના નંબરો તમે આગળ પસંદ કરો છો તે ડિફોલ્ટ નંબર મેળવે છે.',
  'Each enquiry says which form and ad it came from, so you can see which ads bring real enquiries.':
    'દરેક પૂછપરછ કહે છે કે તે કયા ફોર્મ અને જાહેરાતમાંથી આવી છે, જેથી તમે જોઈ શકો કે કઈ જાહેરાતો વાસ્તવિક પૂછપરછ લાવે છે.',
  'Each goes to Meta for review. A submitted template can no longer be edited (only replaced by a new one), so check the drafts first.':
    'દરેક સમીક્ષા માટે મેટા પર જાય છે. સબમિટ કરેલ નમૂનો હવે સંપાદિત કરી શકાતો નથી (ફક્ત નવા દ્વારા બદલવામાં આવે છે), તેથી પહેલા ડ્રાફ્ટ્સ તપાસો.',
  'Each holiday date can be listed once.': 'દરેક રજાની તારીખ એકવાર સૂચિબદ્ધ કરી શકાય છે.',
  'Each link and QR code is tracked separately, so you know what works.':
    'દરેક લિંક અને QR કોડને અલગથી ટ્રૅક કરવામાં આવે છે, જેથી તમે જાણો છો કે શું કામ કરે છે.',
  'Each link carries a short code in its pre-filled message. When the customer sends that first message the code comes back to us, so a website button, an email link and a stall QR code can be told apart — and counted.':
    'દરેક લિંક તેના પહેલાથી ભરેલા સંદેશમાં ટૂંકો કોડ ધરાવે છે. જ્યારે ગ્રાહક તે પહેલો સંદેશ મોકલે છે ત્યારે કોડ અમારી પાસે પાછો આવે છે, તેથી વેબસાઇટ બટન, ઇમેઇલ લિંક અને સ્ટોલ QR કોડને અલગથી કહી શકાય — અને ગણી શકાય.',
