    'જ્યારે તમે એક દાખલ કરો ત્યારે GSTIN માંથી ભરવામાં આવે છે.',
  'Filled in from {0}. Check each field before adding.':
    '{0} થી ભરેલ. ઉમેરતા પહેલા દરેક ફીલ્ડ તપાસો.',
  Filter: 'ફિલ્ટર કરો',
  'Filter by company account': 'કંપની એકાઉન્ટ દ્વારા ફિલ્ટર કરો',
  'Filter by role (Purchase, Maintenance, Plant head…) to reach the right person.':
    'યોગ્ય વ્યક્તિ સુધી પહોંચવા માટે ભૂમિકા દ્વારા ફિલ્ટર કરો (ખરીદી, જાળવણી, પ્લાન્ટ હેડ…).',
  'Filter conversations': 'વાતચીતો ફિલ્ટર કરો',
  'Filter leads': 'ફિલ્ટર લીડ્સ',
  'Filter notifications': 'ફિલ્ટર સૂચનાઓ',
  'Filter to At risk to see the customers who need attention first.':
    'પહેલા ધ્યાનની જરૂર હોય તેવા ગ્રાહકોને જોવા માટે જોખમ પર ફિલ્ટર કરો.',
  'Filter to Critical to see urgent items first.':
    'પહેલા તાકીદની આઇટમ જોવા માટે ક્રિટિકલ પર ફિલ્ટર કરો.',
  "Filters, fan kits, oils: the parts each machine model wears out, and when. A daily check matches every machine on the installed base to these rules; a part shows here once it's within its lead time. Quote a customer's due parts in one go, or record that the part was changed to restart its clock.":
    'ફિલ્ટર્સ, પંખાની કીટ, તેલ: દરેક મશીન મોડલ કયા ભાગો અને ક્યારે પહેરે છે. દૈનિક તપાસ આ નિયમો સાથે સ્થાપિત આધાર પર દરેક મશીન સાથે મેળ ખાય છે; એકવાર તે તેના લીડ ટાઈમમાં આવે તે પછી એક ભાગ અહીં બતાવે છે. ગ્રાહકના બાકી ભાગોને એક જ વારમાં ક્વોટ કરો અથવા રેકોર્ડ કરો કે ભાગ તેની ઘડિયાળને પુનઃપ્રારંભ કરવા માટે બદલાયો હતો.',
