  'Fix deals listed with no close date, or a date that has passed. They are not counted.':
    'કોઈ બંધ તારીખ અથવા વીતી ગયેલી તારીખ વિના સૂચિબદ્ધ સોદાઓને ઠીક કરો. તેમની ગણતરી થતી નથી.',
