  'Flows · MNI Assist': 'પ્રવાહ · MNI સહાય',
  Folder: 'ફોલ્ડર',
  'Follow collections: what was collected, how quickly links are paid, who owes the most and for how long.':
    'સંગ્રહોને અનુસરો: શું એકત્રિત કરવામાં આવ્યું હતું, લિંક્સ કેટલી ઝડપથી ચૂકવવામાં આવે છે, કોને સૌથી વધુ દેવું છે અને કેટલા સમય માટે.',
  "Follow up if there's no answer after (days)": 'જો (દિવસો) પછી કોઈ જવાબ ન હોય તો અનુસરો',
  'Follow up on quotes due today.': 'આજે નિયત અવતરણો પર અનુસરો.',
  'Follow-up': 'ફોલો-અપ',
  'Follow-up template': 'ફોલો-અપ ટેમ્પલેટ',
  'Follow-ups at most': 'વધુમાં વધુ ફોલો-અપ્સ',
  'Followed up{0} {1}': 'અનુસર્યું{0} {1}',
  Food: 'ખોરાક',
  'Food & beverage': 'ખોરાક અને પીણા',
  Footer: 'ફૂટર',
  For: 'માટે',
  'For If… and Wait for a reply, connect both ways out, or leave one empty to end the journey there.':
    'જો માટે… અને જવાબની રાહ જુઓ, બહાર નીકળવાના બંને રસ્તાઓને જોડો, અથવા ત્યાં પ્રવાસ સમાપ્ત કરવા માટે એક ખાલી છોડી દો.',
  "For OEMs and their dealers. As the OEM: invite your dealers, give each a territory, and route enquiries to whoever covers the customer; you then see the dealer's stage, quotes and activity on every lead. As a dealer: enter the OEM's invite code, then accept or decline the leads it sends you.":
    'OEM અને તેમના ડીલરો માટે. OEM તરીકે: તમારા ડીલરોને આમંત્રિત કરો, દરેકને એક પ્રદેશ આપો અને ગ્રાહકને આવરી લેનારને રૂટ પૂછપરછ કરો; પછી તમે દરેક લીડ પર ડીલરનું સ્ટેજ, અવતરણ અને પ્રવૃત્તિ જોશો. ડીલર તરીકે: OEM નો આમંત્રણ કોડ દાખલ કરો, પછી તે તમને મોકલે છે તે લીડ્સ સ્વીકારો અથવા નકારી કાઢો.',
  'For OEMs and their dealers. The OEM invites dealers, gives each a territory and routes enquiries to them. A dealer accepts or declines the leads it is sent.':
    'OEM અને તેમના ડીલરો માટે. OEM ડીલરોને આમંત્રિત કરે છે, દરેકને એક પ્રદેશ આપે છે અને તેમને પૂછપરછનો માર્ગ આપે છે. ડીલર તેને મોકલવામાં આવેલ લીડ્સ સ્વીકારે છે અથવા નકારે છે.',
  'For OEMs with a dealer network and company sign-in.':
    'ડીલર નેટવર્ક અને કંપની સાઇન-ઇન સાથે OEM માટે.',
  'For a closure, tick Out of office, choose the first and last closed day, and write the message.':
    'બંધ કરવા માટે, ઑફિસની બહાર ટિક કરો, પ્રથમ અને છેલ્લો બંધ દિવસ પસંદ કરો અને સંદેશ લખો.',
  'For a request received by email, phone or post. A request that comes through the opt-out keyword is logged automatically.':
    'ઇમેઇલ, ફોન અથવા પોસ્ટ દ્વારા પ્રાપ્ત વિનંતી માટે. એક વિનંતી કે જે ઑપ્ટ-આઉટ કીવર્ડ દ્વારા આવે છે તે આપમેળે લૉગ થાય છે.',
  'For a workspace managing other client workspaces. A client issues an invite code; redeeming it gives read-only access you can enter and exit per client.':
    'અન્ય ક્લાયંટ વર્કસ્પેસનું સંચાલન કરતી વર્કસ્પેસ માટે. ક્લાયંટ એક આમંત્રણ કોડ જારી કરે છે; તેને રિડીમ કરવાથી તમે ક્લાયન્ટ દીઠ દાખલ અને બહાર નીકળી શકો છો તે ફક્ત વાંચવા માટે ઍક્સેસ આપે છે.',
  'For courier rates by PIN code and weight, and shipments that track themselves. Create an API user in Shiprocket (Settings → API) and enter it here. Transporters you book directly work without it.':
    'પિન કોડ અને વજન દ્વારા કુરિયર દરો અને શિપમેન્ટ કે જે પોતાને ટ્રેક કરે છે. Shiprocket (સેટિંગ્સ → API) માં API વપરાશકર્તા બનાવો અને તેને અહીં દાખલ કરો. ટ્રાન્સપોર્ટર્સ જે તમે સીધું બુક કરો છો તે તેના વિના કામ કરે છે.',
  'For how long': 'કેટલા સમય માટે',
  'For machinery makers, OEMs, dealers and service teams.':
    'મશીનરી ઉત્પાદકો, OEMs, ડીલરો અને સેવા ટીમો માટે.',
