  'Generated Flow JSON': 'જનરેટ કરેલ ફ્લો JSON',
  'Generated from your details and retention periods. Have a lawyer review it before you publish it; then record the link and the review date above. The Hindi and Marathi versions are machine-written starting points: have a native speaker check them too.':
    'તમારી વિગતો અને રીટેન્શન અવધિમાંથી જનરેટ થયેલ છે. તમે તેને પ્રકાશિત કરો તે પહેલાં વકીલ પાસે તેની સમીક્ષા કરો; પછી ઉપરની લિંક અને સમીક્ષાની તારીખ રેકોર્ડ કરો. હિન્દી અને મરાઠી સંસ્કરણો મશીન દ્વારા લખાયેલા પ્રારંભિક બિંદુઓ છે: મૂળ વક્તા પાસે પણ તેમને તપાસો.',
  'Generates e-invoices and e-Way Bills from the same records.':
    'સમાન રેકોર્ડમાંથી ઈ-ઈનવોઈસ અને ઈ-વે બિલ જનરેટ કરે છે.',
  'Generating E-Way Bill for Invoice': 'ઇન્વોઇસ માટે ઇ-વે બિલ જનરેટ કરવું',
  'Generating…': 'જનરેટ કરી રહ્યું છે...',
  'Get a desktop alert for WhatsApp calls, even when this window is minimised.':
    'આ વિન્ડો નાની હોય ત્યારે પણ WhatsApp કૉલ્સ માટે ડેસ્કટૉપ ચેતવણી મેળવો.',
  'Get a privacy notice draft, in English, Hindi and Marathi, to give your lawyer.':
    'તમારા વકીલને આપવા માટે અંગ્રેજી, હિન્દી અને મરાઠીમાં ગોપનીયતા સૂચના ડ્રાફ્ટ મેળવો.',
