  'History from both records is kept when you merge.':
    'જ્યારે તમે મર્જ કરો છો ત્યારે બંને રેકોર્ડમાંથી ઇતિહાસ રાખવામાં આવે છે.',
  'History ·': 'ઇતિહાસ ·',
  'Holds each message until the hour that person usually writes to you — learned weekly from their last 90 days of replies, and only once they have at least five. Anyone without enough history goes out at the normal time, and no one is held more than a day. Takes effect when the campaign is sent.':
    'તે વ્યક્તિ સામાન્ય રીતે તમને લખે તે ઘડી સુધી દરેક સંદેશને પકડી રાખે છે — તેમના છેલ્લા 90 દિવસના જવાબોમાંથી સાપ્તાહિક શીખ્યા, અને માત્ર એકવાર તેમની પાસે ઓછામાં ઓછા પાંચ હોય. પર્યાપ્ત ઇતિહાસ વિનાની કોઈપણ વ્યક્તિ સામાન્ય સમયે બહાર જાય છે, અને કોઈને એક દિવસ કરતાં વધુ રાખવામાં આવતું નથી. જ્યારે ઝુંબેશ મોકલવામાં આવે ત્યારે અસર થાય છે.',
