  'If an endpoint is disabled after repeated failures, fix it and click Re-enable.':
    'જો પુનરાવર્તિત નિષ્ફળતાઓ પછી એન્ડપોઇન્ટ અક્ષમ કરવામાં આવે છે, તો તેને ઠીક કરો અને ફરીથી સક્ષમ કરો પર ક્લિક કરો.',
  "If it doesn't match, goes to": 'જો તે મેળ ખાતું નથી, તો જાય છે',
  'If it holds, the steps below this one run.': 'જો તે ધરાવે છે, તો આ એકની નીચેનાં પગલાં ચાલે છે.',
  'If it is high, spread sends over more of the day.':
    'જો તે વધારે હોય, તો સ્પ્રેડ દિવસના વધુ ભાગમાં મોકલે છે.',
  'If it matches': 'જો તે મેળ ખાય છે',
  'If it matches, goes to': 'જો તે મેળ ખાય છે, તો જાય છે',
  'If that address has an account, a confirmation link is on its way. Open it, then sign in again.':
    'જો તે સરનામાંમાં ખાતું હોય, તો પુષ્ટિકરણ લિંક તેના માર્ગ પર છે. તેને ખોલો, પછી ફરીથી સાઇન ઇન કરો.',
  'If the 24-hour window has closed, use Choose a template to start the conversation again.':
    'જો 24-કલાકની વિન્ડો બંધ થઈ ગઈ હોય, તો ફરીથી વાતચીત શરૂ કરવા માટે એક નમૂનો પસંદ કરોનો ઉપયોગ કરો.',
  "If the contact's": 'જો સંપર્ક છે',
  'If the customer messaged in the last 24 hours, the PDF itself goes. Otherwise WhatsApp only accepts an approved template. You will be told if nothing could be sent.':
    'જો ગ્રાહક છેલ્લા 24 કલાકમાં મેસેજ કરે છે, તો પીડીએફ પોતે જ જાય છે. અન્યથા WhatsApp માત્ર માન્ય ટેમ્પલેટ સ્વીકારે છે. જો કંઈ મોકલી શકાય તેમ ન હોય તો તમને જણાવવામાં આવશે.',
  'If there is an account for': 'માટે ખાતું હોય તો',
  "If they don't reply within {0} hours": 'જો તેઓ {0} કલાકની અંદર જવાબ ન આપે',
  "If they don't reply, goes to": 'જો તેઓ જવાબ ન આપે, તો જાય છે',
  'If they reply': 'જો તેઓ જવાબ આપે',
  'If they reply, goes to': 'જો તેઓ જવાબ આપે છે, તો જાય છે',
  'If they reply, the steps below this one run.':
    'જો તેઓ જવાબ આપે છે, તો આના નીચેના પગલાંઓ ચાલે છે.',
  'If this lasts more than a few minutes, the platform may be down. Messages sent to your WhatsApp number are held by Meta and delivered when we are back.':
    'જો આ થોડી મિનિટો કરતાં વધુ ચાલે છે, તો પ્લેટફોર્મ ડાઉન થઈ શકે છે. તમારા WhatsApp નંબર પર મોકલવામાં આવેલા સંદેશાઓ મેટા દ્વારા રાખવામાં આવે છે અને જ્યારે અમે પાછા આવીએ છીએ ત્યારે વિતરિત કરવામાં આવે છે.',
  'If this number already has a WhatsApp PIN, use it. Otherwise, choose six digits and keep them safe. This is not the verification code sent by SMS.':
    'જો આ નંબર પર પહેલેથી જ WhatsApp પિન છે, તો તેનો ઉપયોગ કરો. નહિંતર, છ અંકો પસંદ કરો અને તેમને સુરક્ષિત રાખો. આ SMS દ્વારા મોકલવામાં આવેલ ચકાસણી કોડ નથી.',
  "If you are a contact a tenant has messaged, or a member of a tenant's team, you can ask the tenant (as the party responsible for your data — see §7) to:":
    'જો તમે ભાડૂતને સંદેશ મોકલેલ સંપર્ક અથવા ભાડૂતની ટીમના સભ્ય છો, તો તમે ભાડૂતને (તમારા ડેટા માટે જવાબદાર પક્ષ તરીકે — §7 જુઓ) પૂછી શકો છો:',
  'If you hold no data about this person, reject the request and tell them so.':
    'જો તમારી પાસે આ વ્યક્તિ વિશે કોઈ ડેટા નથી, તો વિનંતીને નકારી કાઢો અને તેમને કહો.',
  'If you received a message through MNI Assist, the business that messaged you (the "tenant") is who asked for your consent and is responsible for deciding what to send you — they are the data fiduciary under India\'s Digital Personal Data Protection Act, 2023. MNI Assist (Emnisoft Pvt Ltd) processes that data on the tenant\'s instructions, as its data processor / significant processing platform.':
    'જો તમને MNI આસિસ્ટ દ્વારા સંદેશ પ્રાપ્ત થયો હોય, તો તમને સંદેશ મોકલનાર વ્યવસાય ("ભાડૂત") એ તમારી સંમતિ માંગી છે અને તમને શું મોકલવું તે નક્કી કરવા માટે જવાબદાર છે — તેઓ ભારતના ડિજિટલ પર્સનલ ડેટા પ્રોટેક્શન એક્ટ, 2023 હેઠળ ડેટા વિશ્વાસપાત્ર છે. MNI આસિસ્ટ (Emnisoft Pvt Ltd) તે ડેટા પર પ્રક્રિયા કરે છે જે ભાડૂતના ડેટા / પ્લેટફોર્મ પર નોંધપાત્ર પ્રક્રિયા કરે છે.',
