  'Issuing makes the PDF final and starts the follow-up cadence. Total {0} including GST.':
    'જારી કરવાથી પીડીએફ અંતિમ બને છે અને ફોલો-અપ કેડન્સ શરૂ થાય છે. GST સહિત કુલ {0}.',
  'Issuing…': 'જારી કરી રહ્યાં છીએ...',
  'It also hands off — without calling the model — when a customer asks for a person, raises a complaint, sends a photo or location, or when a colleague has already picked up the conversation.':
    'જ્યારે કોઈ ગ્રાહક કોઈ વ્યક્તિ માટે પૂછે છે, ફરિયાદ કરે છે, ફોટો અથવા સ્થાન મોકલે છે અથવા જ્યારે કોઈ સાથીદારે પહેલેથી જ વાતચીત પસંદ કરી લીધી હોય ત્યારે - તે મોડલને કૉલ કર્યા વિના - હાથ પણ બંધ કરે છે.',
  'It becomes version {0}. Every send from now on carries the new file; the old one is not kept.':
    'તે સંસ્કરણ {0} બને છે. હવેથી દરેક મોકલો નવી ફાઇલ વહન કરે છે; જૂનું રાખવામાં આવ્યું નથી.',
  'It disappears from the status page history. Resolve it instead if it really happened.':
    'તે સ્થિતિ પૃષ્ઠ ઇતિહાસમાંથી અદૃશ્ય થઈ જાય છે. જો તે ખરેખર બન્યું હોય તો તેના બદલે તેને ઉકેલો.',
  'It failed again.': 'તે ફરી નિષ્ફળ ગયો.',
  'It goes back to them to offer elsewhere.': 'તે અન્યત્ર ઓફર કરવા માટે તેમને પાછા જાય છે.',
  'It has to sign in again to use your account.':
    'તમારા એકાઉન્ટનો ઉપયોગ કરવા માટે તેને ફરીથી સાઇન ઇન કરવું પડશે.',
  'It is shown once. Copy it now, or send it from here.':
    'તે એકવાર બતાવવામાં આવે છે. તેને હમણાં કૉપિ કરો, અથવા તેને અહીંથી મોકલો.',
  'It may have been deleted or moved.': 'તે કાઢી નાખવામાં અથવા ખસેડવામાં આવી શકે છે.',
  'It reads and writes the shared database from now on. Its own database is left as it is, not deleted, and nothing in it is copied back.':
    'તે હવેથી વહેંચાયેલ ડેટાબેઝ વાંચે છે અને લખે છે. તેનો પોતાનો ડેટાબેઝ જેમ છે તેમ છોડી દેવામાં આવે છે, કાઢી નાખવામાં આવતો નથી, અને તેમાંની કોઈ પણ વસ્તુની નકલ કરવામાં આવતી નથી.',
  'It stays live for sessions already in progress, but cannot be sent again.':
    'તે પહેલાથી ચાલી રહેલા સત્રો માટે લાઇવ રહે છે, પરંતુ ફરીથી મોકલી શકાતું નથી.',
  'It still has {0} enquir{1}: choose where they go. Each lands in the matching stage.':
    'તેની પાસે હજુ પણ {0} પૂછપરછ{1} છે: તેઓ ક્યાં જાય છે તે પસંદ કરો. દરેક મેચિંગ સ્ટેજમાં ઉતરે છે.',
  'It stops counting towards this partner’s client limit and earns no further commission.':
    'તે આ ભાગીદારની ક્લાયંટ મર્યાદામાં ગણતરી કરવાનું બંધ કરે છે અને કોઈ વધુ કમિશન મેળવતું નથી.',
  Item: 'વસ્તુ',
  Items: 'વસ્તુઓ',
  'Items & Qty': 'વસ્તુઓ અને જથ્થો',
  'Items to Debit': 'ડેબિટ કરવા માટે વસ્તુઓ',
  'Its address is given once you save.': 'એકવાર તમે સેવ કરો ત્યારે તેનું સરનામું આપવામાં આવે છે.',
  'Its link stops working. You can send a new request later.':
    'તેની લિંક કામ કરવાનું બંધ કરી દે છે. તમે પછીથી નવી વિનંતી મોકલી શકો છો.',
  'Its members can sign in again straight away.': 'તેના સભ્યો તરત જ ફરીથી સાઇન ઇન કરી શકે છે.',
