  'Join steps in order. On the canvas, drag from the dot on a step’s bottom edge to the next step.':
    'ક્રમમાં પગલાં જોડાઓ. કેનવાસ પર, એક સ્ટેપની નીચેની કિનારી પરના ડોટમાંથી આગળના સ્ટેપ પર ખેંચો.',
  'Join: {0}': 'જોડાઓ: {0}',
  "Joining an OEM's dealer network and receiving its leads is free on every plan. Running your own dealer network (inviting dealers and routing leads to them) is part of Enterprise.":
    'OEM ના ડીલર નેટવર્કમાં જોડાવું અને તેની લીડ મેળવવી એ દરેક યોજના પર મફત છે. તમારું પોતાનું ડીલર નેટવર્ક ચલાવવું (ડીલરોને આમંત્રિત કરવા અને તેમને રાઉટીંગ કરવા) એ એન્ટરપ્રાઇઝનો એક ભાગ છે.',
  'Joining…': 'જોડાઈ રહ્યું છે...',
  'Journal Voucher': 'જર્નલ વાઉચર',
  'Journal Vouchers (Double-Entry General Ledger)': 'જર્નલ વાઉચર્સ (ડબલ-એન્ટ્રી જનરલ લેજર)',
  'Journal vouchers · MNI Assist': 'જર્નલ વાઉચર્સ · MNI આસિસ્ટ',
  July: 'જુલાઈ',
  June: 'જૂન',
  'Just now': 'હમણાં જ',
  'KYC Cleared': 'KYC ક્લિયર',
  'KYC: {0}': 'KYC: {0}',
  'Keep A parts always in stock and count them often; B parts on a steady reorder; C parts ordered as needed.':
    'A ભાગોને હંમેશા સ્ટોકમાં રાખો અને તેને વારંવાર ગણો; સ્થિર પુનઃક્રમમાં બી ભાગો; સી ભાગો જરૂર તરીકે ઓર્ડર.',
  'Keep a record of retention settings and any breaches.':
    'રીટેન્શન સેટિંગ્સ અને કોઈપણ ઉલ્લંઘનનો રેકોર્ડ રાખો.',
  'Keep call': 'કૉલ રાખો',
  'Keep details in step with Meta.': 'મેટા સાથે પગલામાં વિગતો રાખો.',
  'Keep each number’s KYC up to date, and run the compliance audit regularly.':
    'દરેક નંબરના કેવાયસીને અદ્યતન રાખો અને નિયમિતપણે અનુપાલન ઓડિટ ચલાવો.',
  'Keep editing': 'સંપાદન કરતા રહો',
  'Keep every machine you sold earning after the sale.':
    'તમે વેચેલા દરેક મશીનને વેચાણ પછી કમાણી રાખો.',
  'Keep for': 'માટે રાખો',
  'Keep it': 'રાખો',
  'Keep only one active list for each region and tier, so the right price is always clear.':
    'દરેક ક્ષેત્ર અને સ્તર માટે માત્ર એક સક્રિય સૂચિ રાખો, જેથી યોગ્ય કિંમત હંમેશા સ્પષ્ટ રહે.',
  'Keep the current default': 'વર્તમાન ડિફોલ્ટ રાખો',
  'Keep the menu to three levels — that is what the flow above can serve, and the depth Exotel itself recommends. The third menu can only transfer or end the call.':
    'મેનૂને ત્રણ સ્તરો પર રાખો - તે ઉપરનો પ્રવાહ સેવા આપી શકે છે, અને ઊંડાઈ Exotel પોતે ભલામણ કરે છે. ત્રીજું મેનૂ ફક્ત કૉલને સ્થાનાંતરિત અથવા સમાપ્ત કરી શકે છે.',
  'Keep this tab open until the call ends: the audio passes through it.':
    'જ્યાં સુધી કૉલ સમાપ્ત ન થાય ત્યાં સુધી આ ટેબને ખુલ્લું રાખો: ઑડિયો તેમાંથી પસાર થાય છે.',
  'Keep which record?': 'કયો રેકોર્ડ રાખો?',
  'Keep with the enquiry': 'પૂછપરછ સાથે રાખો',
  'Keep your CRM in step without retyping.': 'ફરીથી ટાઇપ કર્યા વિના તમારા CRM ને સ્ટેપમાં રાખો.',
  'Keep your existing business number when moving to MNI Assist.':
    'MNI આસિસ્ટ પર જતી વખતે તમારો હાલનો બિઝનેસ નંબર રાખો.',
  'Keep your name and contact details current for your team.':
    'તમારી ટીમ માટે તમારું નામ અને સંપર્ક વિગતો વર્તમાન રાખો.',
  'Keep | html.escape on names and anything else a person typed.':
    'રાખો | html.escape નામો અને અન્ય કોઈ પણ વ્યક્તિએ ટાઈપ કર્યું છે.',
  "Keeping it here lets the re-order portal show customers what's in stock, holds parts for their requests, and issues them when a quotation is won.":
    'તેને અહીં રાખવાથી પોર્ટલ પુનઃ-ઓર્ડર ગ્રાહકોને બતાવી શકે છે કે સ્ટોકમાં શું છે, તેમની વિનંતીઓ માટેના ભાગો ધરાવે છે અને જ્યારે ક્વોટેશન જીતવામાં આવે ત્યારે તેમને જારી કરે છે.',
  'Keeps every maintenance contract, its visits and its renewal date in one place.':
    'દરેક જાળવણી કરાર, તેની મુલાકાતો અને તેની નવીકરણ તારીખ એક જગ્યાએ રાખે છે.',
  'Keeps the vendor’s balance correct for GST input credit.':
    'GST ઇનપુટ ક્રેડિટ માટે વેન્ડરનું બેલેન્સ યોગ્ય રાખે છે.',
  Kept: 'રાખ્યું',
  'Kept on the audit record.': 'ઓડિટ રેકોર્ડ પર રાખવામાં આવે છે.',
  'Kept with the workspace. Only the server and database name are shown again, never the password.':
    'વર્કસ્પેસ સાથે રાખવામાં આવે છે. ફક્ત સર્વર અને ડેટાબેઝ નામ જ ફરીથી બતાવવામાં આવે છે, પાસવર્ડ ક્યારેય નહીં.',
