  'Know every person you deal with at one customer.':
    'એક ગ્રાહક પર તમે જેની સાથે વ્યવહાર કરો છો તે દરેક વ્યક્તિને જાણો.',
  'Know how many of each part you have at each location.':
    'દરેક સ્થાન પર તમારી પાસે દરેક ભાગમાંથી કેટલા છે તે જાણો.',
  'Know the value of stock on the shelves and how many days of sales it represents.':
    'છાજલીઓ પરના સ્ટોકનું મૂલ્ય અને તે વેચાણના કેટલા દિવસોનું પ્રતિનિધિત્વ કરે છે તે જાણો.',
