  'Leads missed while the connection was down are fetched automatically every 15 minutes.':
    'જ્યારે કનેક્શન ડાઉન હતું ત્યારે લીડ્સ છૂટી જાય છે તે દર 15 મિનિટે આપમેળે મેળવવામાં આવે છે.',
  'Leads that stall can be taken back or routed again, so none are lost.':
    'લીડ્સ કે જે સ્ટોલને પાછા લઈ શકાય છે અથવા ફરીથી રૂટ કરી શકાય છે, જેથી કોઈ ખોવાઈ જાય નહીં.',
