  'MNI Assist': 'MNI આસિસ્ટ',
  'MNI Assist is a WhatsApp, SMS, Email, Instagram and Messenger marketing platform built for industrial automation businesses in India to reach their own customers. This policy explains what personal data we process when a business (a "tenant") uses MNI Assist to message':
    'MNI આસિસ્ટ એ WhatsApp, SMS, Email, Instagram અને Messenger માર્કેટિંગ પ્લેટફોર્મ છે જે ભારતમાં ઔદ્યોગિક ઓટોમેશન વ્યવસાયો માટે તેમના પોતાના ગ્રાહકો સુધી પહોંચવા માટે બનાવવામાં આવ્યું છે. આ નીતિ સમજાવે છે કે જ્યારે કોઈ વ્યવસાય ("ભાડૂત") સંદેશ માટે MNI સહાયનો ઉપયોગ કરે છે ત્યારે અમે કયા વ્યક્તિગત ડેટા પર પ્રક્રિયા કરીએ છીએ',
  'MNI Assist is a business-to-business messaging tool. It is not directed at children, and we do not knowingly process the personal data of anyone under 18 as a contact in their own right.':
    'MNI આસિસ્ટ એ બિઝનેસ-ટુ-બિઝનેસ મેસેજિંગ ટૂલ છે. તે બાળકો માટે નિર્દેશિત નથી, અને અમે જાણી જોઈને 18 વર્ષથી ઓછી ઉંમરના કોઈપણ વ્યક્તિના વ્યક્તિગત ડેટાને તેમના પોતાના અધિકારમાં સંપર્ક તરીકે પ્રક્રિયા કરતા નથી.',
  'MNI Assist looks like your own product to your team.':
    'MNI આસિસ્ટ તમારી ટીમને તમારા પોતાના ઉત્પાદન જેવું લાગે છે.',
  'MNI Assist only reads spend (Meta’s ads_read permission). It cannot create, change or pause ads.':
    'MNI આસિસ્ટ માત્ર ખર્ચ વાંચે છે (મેટાની જાહેરાતો_વાંચવાની પરવાનગી). તે જાહેરાતો બનાવી, બદલી કે થોભાવી શકતી નથી.',
  'MNI Assist shared relay': 'MNI આસિસ્ટ શેર્ડ રિલે',
  'MNI Assist suggests likely duplicates by shared phone number, email address, or name. Nothing is merged automatically: review a pair, choose which record to keep, and check the preview before you confirm.':
    'MNI આસિસ્ટ શેર કરેલ ફોન નંબર, ઇમેઇલ સરનામું અથવા નામ દ્વારા સંભવિત ડુપ્લિકેટ સૂચવે છે. કંઈપણ આપમેળે મર્જ થતું નથી: જોડીની સમીક્ષા કરો, કયો રેકોર્ડ રાખવો તે પસંદ કરો અને તમે પુષ્ટિ કરો તે પહેલાં પૂર્વાવલોકન તપાસો.',
  'MNI Assist support can enter your workspace until the grant expires or you revoke it. Every action they take is logged below.':
    'જ્યાં સુધી ગ્રાન્ટ સમાપ્ત ન થાય અથવા તમે તેને રદ ન કરો ત્યાં સુધી MNI આસિસ્ટ સપોર્ટ તમારા વર્કસ્પેસમાં પ્રવેશી શકે છે. તેઓ કરે છે તે દરેક ક્રિયા નીચે લોગ થયેલ છે.',
  'MNI Assist · AI Business Engagement Platform for Industrial Companies':
    'MNI આસિસ્ટ · ઔદ્યોગિક કંપનીઓ માટે AI બિઝનેસ એન્ગેજમેન્ટ પ્લેટફોર્મ',
  'MNI Assist — AI Business Engagement Platform for Industrial Companies ·':
    'MNI આસિસ્ટ - ઔદ્યોગિક કંપનીઓ માટે AI બિઝનેસ એન્ગેજમેન્ટ પ્લેટફોર્મ ·',
  'MNI Assist — two-step verification recovery codes':
    'MNI આસિસ્ટ — બે-પગલાંની ચકાસણી પુનઃપ્રાપ્તિ કોડ્સ',
  "MNI Assist's AI reads the conversation and your own knowledge base, then suggests the next reply. Nothing reaches a customer without a person, unless you switch on the assistant for questions it can answer with confidence.":
    'MNI આસિસ્ટનું AI વાતચીત અને તમારા પોતાના જ્ઞાન આધારને વાંચે છે, પછી આગળનો જવાબ સૂચવે છે. કોઈ વ્યક્તિ વિના ગ્રાહક સુધી કંઈ જ પહોંચતું નથી, સિવાય કે તમે પ્રશ્નો માટે સહાયકને સ્વિચ કરો તે વિશ્વાસપૂર્વક જવાબ આપી શકે.',
