  'Made {0}. Each code works once.': '{0} બનાવ્યું. દરેક કોડ એકવાર કામ કરે છે.',
  Maharashtra: 'મહારાષ્ટ્ર',
  'Mail leaves under your own domain and your own SPF/DKIM signature, so deliverability and bounces are yours to manage. Use the server your email provider gives you (Google Workspace, Microsoft 365, Zoho, SendGrid, Amazon SES…).':
    'તમારા પોતાના ડોમેન અને તમારા પોતાના SPF/DKIM હસ્તાક્ષર હેઠળ મેઇલ છોડે છે, તેથી ડિલિવરીબિલિટી અને બાઉન્સનું સંચાલન કરવાનું તમારું છે. તમારા ઇમેઇલ પ્રદાતા તમને આપે છે તે સર્વરનો ઉપયોગ કરો (Google Workspace, Microsoft 365, Zoho, SendGrid, Amazon SES…).',
