  'Manage user permissions': 'વપરાશકર્તા પરવાનગીઓ મેનેજ કરો',
  'Manage your virtual WhatsApp number inventory pool, allocate numbers to tenant workspaces, and maintain regulatory compliance under the Telecommunications Act 2023, TRAI DLT, and Meta Tech Provider guidelines.':
    'તમારા વર્ચ્યુઅલ WhatsApp નંબર ઈન્વેન્ટરી પૂલને મેનેજ કરો, ભાડૂત વર્કસ્પેસને નંબરો ફાળવો અને ટેલિકોમ્યુનિકેશન એક્ટ 2023, TRAI DLT અને મેટા ટેક પ્રોવાઈડર માર્ગદર્શિકા હેઠળ નિયમનકારી અનુપાલન જાળવો.',
