  Marketing: 'માર્કેટિંગ',
  'Marketing Messages Lite (MM Lite send path)':
    'માર્કેટિંગ મેસેજીસ લાઇટ (એમએમ લાઇટ મોકલવાનો માર્ગ)',
  'Marketing and service messages': 'માર્કેટિંગ અને સેવા સંદેશા',
  "Marketing and utility are priced against different audiences on purpose: one reaches the opted-in, the other reaches nearly everyone. Both are estimates — billing follows Meta's delivery receipt, so an undelivered or withheld message is never charged.":
    'માર્કેટિંગ અને ઉપયોગિતાની કિંમત અલગ-અલગ પ્રેક્ષકો સામે હેતુપૂર્વક નક્કી કરવામાં આવે છે: એક પસંદ કરેલ વ્યક્તિ સુધી પહોંચે છે, અન્ય લગભગ દરેક વ્યક્તિ સુધી પહોંચે છે. બંને અંદાજો છે — બિલિંગ મેટાની ડિલિવરી રસીદને અનુસરે છે, તેથી વિતરિત અથવા રોકેલા સંદેશ પર ક્યારેય શુલ્ક લેવામાં આવતો નથી.',
  "Marketing email goes out from the sender you set here, either through MNI Assist's shared relay or through your own SMTP server. Every marketing email carries a one-click unsubscribe link automatically.":
    'માર્કેટિંગ ઈમેઈલ તમે અહીં સેટ કરેલ પ્રેષક તરફથી બહાર આવે છે, કાં તો MNI આસિસ્ટના શેર કરેલ રિલે દ્વારા અથવા તમારા પોતાના SMTP સર્વર દ્વારા. દરેક માર્કેટિંગ ઇમેઇલ એક-ક્લિક અનસબ્સ્ક્રાઇબ લિંકને આપમેળે વહન કરે છે.',
  'Marketing email goes out under your own sender name.':
    'માર્કેટિંગ ઇમેઇલ તમારા પોતાના પ્રેષકના નામ હેઠળ બહાર જાય છે.',
  'Marketing email is paused platform-wide: unsubscribe links cannot be built ({0}). Ask your MNI Assist administrator to fix this — sending without an unsubscribe link is not allowed.':
    'માર્કેટિંગ ઈમેલ પ્લેટફોર્મ-વ્યાપી થોભાવેલ છે: અનસબ્સ્ક્રાઇબ લિંક્સ બનાવી શકાતી નથી ({0}). તમારા MNI આસિસ્ટ એડમિનિસ્ટ્રેટરને આને ઠીક કરવા માટે કહો — અનસબ્સ્ક્રાઇબ લિંક વિના મોકલવાની મંજૂરી નથી.',
  'Marketing needs a real opt-in. A list without one is kept to service messages, whatever is chosen here.':
    'માર્કેટિંગને વાસ્તવિક ઑપ્ટ-ઇનની જરૂર છે. એક વિનાની યાદી સેવા સંદેશાઓ માટે રાખવામાં આવે છે, જે અહીં પસંદ કરવામાં આવે છે.',
