  Orders: 'ઓર્ડર',
  'Orders directly': 'સીધા ઓર્ડર',
  "Orders outside these terms still reach you, flagged with why. The customer only hears that you'll be in touch. Orders paid up front aren't affected.":
    'આ શરતોની બહારના ઓર્ડર હજુ પણ તમારા સુધી પહોંચે છે, શા માટે ફ્લેગ કરેલ છે. ગ્રાહક માત્ર સાંભળે છે કે તમે સંપર્કમાં હશો. ફ્રન્ટ ચુકવાયેલા ઓર્ડરને અસર થતી નથી.',
  "Orders to suppliers, received into stock at their cost. Stock is valued at moving average cost, the method Tally's Average Cost and SAP Business One's Moving Average use. Sent orders count as on order on the Stock page.":
    'સપ્લાયરો માટે ઓર્ડર, તેમની કિંમતે સ્ટોકમાં પ્રાપ્ત. મૂવિંગ એવરેજ કોસ્ટ, મેથડ ટેલીની એવરેજ કોસ્ટ અને SAP બિઝનેસ વનના મૂવિંગ એવરેજ ઉપયોગ પર સ્ટોકનું મૂલ્ય છે. મોકલેલા ઓર્ડર સ્ટોક પેજ પરના ઓર્ડર પ્રમાણે ગણાય છે.',
