  "Point your identity provider's issuer at MNI Assist and map the email domains it owns. People signing in from those domains are provisioned automatically with the role below.":
    'તમારા ઓળખ પ્રદાતાના રજૂકર્તાને MNI આસિસ્ટ પર નિર્દેશ કરો અને તેની માલિકીના ઇમેઇલ ડોમેન્સનો નકશો બનાવો. તે ડોમેન્સમાંથી સાઇન ઇન કરનારા લોકો નીચેની ભૂમિકા સાથે આપમેળે જોગવાઈ કરે છે.',
  'Points from 0 to 100. Penalties are taken away, rewards added; “at most” caps how much one kind of signal can move a score. Saving rescores every customer.':
    '0 થી 100 સુધીના પોઈન્ટ્સ. દંડ લેવામાં આવે છે, પુરસ્કારો ઉમેરવામાં આવે છે; એક પ્રકારનું સિગ્નલ સ્કોરને કેટલું ખસેડી શકે છે તે “વધુમાં વધુ” દર્શાવે છે. બચત દરેક ગ્રાહકને બચાવે છે.',
