  'Quality inspection decides what goes into stock and what is sent back.':
    'ગુણવત્તા નિરીક્ષણ નક્કી કરે છે કે સ્ટોકમાં શું જાય છે અને શું પાછું મોકલવામાં આવે છે.',
  'Quantities of each catalogue part at each location. Every change is a movement (received, issued, adjusted, counted), so the history explains every figure. Parts on an open re-order request are held (reserved) until the quotation is won or lost; a won quotation issues its parts.':
    'દરેક સ્થાન પર દરેક સૂચિ ભાગની માત્રા. દરેક ફેરફાર એક ચળવળ છે (પ્રાપ્ત, જારી, સમાયોજિત, ગણતરી), તેથી ઇતિહાસ દરેક આકૃતિને સમજાવે છે. ઓપન રિ-ઓર્ડર વિનંતી પરના ભાગો જ્યાં સુધી અવતરણ જીતી અથવા હારી ન જાય ત્યાં સુધી રાખવામાં આવે છે (આરક્ષિત); જીતેલા અવતરણ તેના ભાગોને રજૂ કરે છે.',
