  'Select Download when it is Ready, or use the link in the email.':
    'જ્યારે તે તૈયાર હોય ત્યારે ડાઉનલોડ કરો પસંદ કરો અથવા ઇમેઇલમાંની લિંકનો ઉપયોગ કરો.',
  'Select Plan': 'પ્લાન પસંદ કરો',
  'Select a negotiation session from the list to view its details.':
    'તેની વિગતો જોવા માટે સૂચિમાંથી વાટાઘાટ સત્ર પસંદ કરો.',
  'Select a prompt…': 'પ્રોમ્પ્ટ પસંદ કરો...',
  "Select a step to change it. Drag from the dot on a step's bottom edge to the step that should come next; a dot left hollow ends the journey there.":
    'તેને બદલવા માટે એક પગલું પસંદ કરો. એક પગલાની નીચેની ધાર પરના બિંદુથી આગળના પગલા પર ખેંચો; એક ટપકું ડાબું હોલો ત્યાં પ્રવાસ સમાપ્ત કરે છે.',
  'Select all calls shown': 'દર્શાવેલ તમામ કોલ્સ પસંદ કરો',
  'Selected calls': 'પસંદ કરેલા કૉલ્સ',
