  'Self Delivery': 'સ્વ ડિલિવરી',
  Sell: 'વેચો',
  'Sell AutoReach to your own clients under your brand. You register once; the platform team reviews and approves you, then you can set up your branding and domain, add client workspaces and earn commission on what they pay.':
    'તમારી બ્રાન્ડ હેઠળ તમારા પોતાના ગ્રાહકોને AutoReach વેચો. તમે એકવાર નોંધણી કરો; પ્લેટફોર્મ ટીમ તમારી સમીક્ષા કરે છે અને મંજૂર કરે છે, પછી તમે તમારું બ્રાન્ડિંગ અને ડોમેન સેટ કરી શકો છો, ક્લાયન્ટ વર્કસ્પેસ ઉમેરી શકો છો અને તેઓ જે ચૂકવે છે તેના પર કમિશન મેળવી શકો છો.',
  'Sell consumables (filters, kits, oils) when customers actually need them.':
    'જ્યારે ગ્રાહકોને ખરેખર તેની જરૂર હોય ત્યારે ઉપભોક્તા (ફિલ્ટર, કિટ્સ, તેલ) વેચો.',
  'Sell the machine once, then keep the customer for its whole life.':
    'એકવાર મશીન વેચો, પછી ગ્રાહકને તેની આખી જીંદગી રાખો.',
