  "Send a customer a payment link from their conversation in the inbox. They pay on BillDesk's secure page by UPI, card or net banking, into your own BillDesk merchant account. A request is marked paid only when BillDesk's signed confirmation arrives for exactly the amount asked.":
    'ગ્રાહકને ઇનબૉક્સમાં તેમની વાતચીતમાંથી ચુકવણીની લિંક મોકલો. તેઓ બિલડેસ્કના સુરક્ષિત પેજ પર UPI, કાર્ડ અથવા નેટ બેંકિંગ દ્વારા તમારા પોતાના બિલડેસ્ક વેપારી ખાતામાં ચૂકવણી કરે છે. જ્યારે બિલડેસ્કની સહી કરેલ પુષ્ટિ પૂછવામાં આવેલી બરાબર રકમ માટે આવે ત્યારે જ વિનંતીને ચૂકવેલ તરીકે ચિહ્નિત કરવામાં આવે છે.',
