  'Set a new password for anyone in this workspace — for an owner who is locked out, for example. Their current password is not needed. They are signed out everywhere, and are asked to choose their own at the next sign-in unless you untick that.':
    'આ કાર્યસ્થળમાં કોઈપણ માટે નવો પાસવર્ડ સેટ કરો — ઉદાહરણ તરીકે, લૉક આઉટ થયેલા માલિક માટે. તેમના વર્તમાન પાસવર્ડની જરૂર નથી. તેઓ દરેક જગ્યાએ સાઇન આઉટ થાય છે, અને જ્યાં સુધી તમે તેને અનટિક ન કરો ત્યાં સુધી આગલા સાઇન-ઇન પર તેમની પોતાની પસંદગી કરવાનું કહેવામાં આવે છે.',
