  'Sorry about that, Mr. Kulkarni. Your machine is under AMC, so the visit is covered. I have raised a service ticket and an engineer will call you today.':
    'તેના માટે માફ કરશો, શ્રી કુલકર્ણી. તમારું મશીન AMC હેઠળ છે, તેથી મુલાકાત આવરી લેવામાં આવી છે. મેં સર્વિસ ટિકિટ વધારી છે અને આજે તમને એક એન્જિનિયર બોલાવશે.',
