  'Spend, template, agent and conversion reports come with full analytics, which your plan does not include. The daily volume chart works on every plan; ask your MNI Assist contact to switch full analytics on.':
    'ખર્ચ, નમૂનો, એજન્ટ અને રૂપાંતરણ અહેવાલો સંપૂર્ણ એનાલિટિક્સ સાથે આવે છે, જેનો તમારી યોજનામાં સમાવેશ થતો નથી. દૈનિક વોલ્યુમ ચાર્ટ દરેક યોજના પર કામ કરે છે; તમારા MNI સહાયક સંપર્કને સંપૂર્ણ એનાલિટિક્સ ચાલુ કરવા માટે કહો.',
