  'Tenant data is isolated per workspace at the database level. Access-control tokens and channel credentials are stored in an encrypted secret store, never alongside ordinary data. Administrative access to the platform is role-permissioned and logged. No security measure is perfect; see §8 for how to report a concern.':
    'ડેટાબેઝ સ્તર પર વર્કસ્પેસ દીઠ ભાડૂત ડેટાને અલગ કરવામાં આવે છે. એક્સેસ-કંટ્રોલ ટોકન્સ અને ચેનલ ઓળખપત્રો એનક્રિપ્ટેડ સિક્રેટ સ્ટોરમાં સંગ્રહિત થાય છે, સામાન્ય ડેટાની સાથે ક્યારેય નહીં. પ્લેટફોર્મ પર વહીવટી ઍક્સેસ રોલ-પરમિશન અને લોગ થયેલ છે. કોઈ સુરક્ષા માપદંડ સંપૂર્ણ નથી; ચિંતાની જાણ કેવી રીતે કરવી તે માટે §8 જુઓ.',
