  'The call could not be placed.': 'કૉલ કરી શકાયો નથી.',
  'The call could not be rejoined. It may have ended.':
    'કૉલ ફરી જોડાઈ શક્યો નથી. તે સમાપ્ત થઈ શકે છે.',
  'The call could not be transferred.': 'કૉલ ટ્રાન્સફર કરી શકાયો નથી.',
  'The call log could not be loaded.': 'કૉલ લોગ લોડ કરી શકાયો નથી.',
