  'The changes to this quotation have not been saved.': 'આ અવતરણમાંના ફેરફારો સાચવવામાં આવ્યા નથી.',
  'The changes to this template have not been saved.': 'આ નમૂનામાંના ફેરફારો સાચવવામાં આવ્યા નથી.',
