  'Ticket Number': 'ટિકિટ નંબર',
  'Ticket TK-2481 raised. Ravi from field service will visit tomorrow at 10 am.':
    'ટિકિટ TK-2481 વધારી. ક્ષેત્ર સેવામાંથી રવિ આવતીકાલે સવારે 10 વાગ્યે મુલાકાત લેશે.',
  'Ticket Type': 'ટિકિટનો પ્રકાર',
  'Ticket reference': 'ટિકિટ સંદર્ભ',
  'Ticket, quotation, re-order or payment link': 'ટિકિટ, અવતરણ, ફરીથી ઓર્ડર અથવા ચુકવણી લિંક',
  'Tickets could not be loaded.': 'ટિકિટ લોડ કરી શકાઈ નથી.',
  "Ticking a box records the visitor's word, not proof that the number or address is theirs. Marketing messages to a number nobody has confirmed carry a risk.":
    'બૉક્સ પર નિશાની કરવાથી મુલાકાતીનો શબ્દ નોંધવામાં આવે છે, નંબર અથવા સરનામું તેમનો છે તે પુરાવો નથી. કોઈએ પુષ્ટિ ન કરી હોય તેવા નંબર પરના માર્કેટિંગ સંદેશાઓ જોખમ ધરાવે છે.',
