  Track: 'ટ્રેક',
  'Track a part by batch (oils, filters with a shelf life) or by serial number (drives, controllers, anything under warranty). Every unit received then needs its number, issues take the soonest expiry or oldest first, and any number can be traced to the customer it went to. Change it only while none is in stock: count it to zero first.':
    'બેચ (તેલ, શેલ્ફ લાઇફ સાથેના ફિલ્ટર્સ) અથવા સીરીયલ નંબર (ડ્રાઇવ, કંટ્રોલર, વૉરંટી હેઠળની કોઈપણ વસ્તુ) દ્વારા ભાગને ટ્રૅક કરો. પ્રાપ્ત થયેલ દરેક એકમને પછી તેના નંબરની જરૂર હોય છે, સમસ્યાઓ સૌથી વહેલા સમાપ્ત થાય છે અથવા સૌથી જૂની હોય છે, અને કોઈપણ નંબર તે ગ્રાહકને શોધી શકે છે જેની પાસે તે ગયો હતો. જ્યારે કોઈ સ્ટોકમાં ન હોય ત્યારે જ તેને બદલો: પહેલા તેને શૂન્યમાં ગણો.',
