  'Turn one feature on or off for this workspace whatever its plan says. “As the plan says” removes the override.':
    'આ વર્કસ્પેસ માટે એક સુવિધા ચાલુ અથવા બંધ કરો જે તેની યોજના કહે છે. "જેમ કે યોજના કહે છે" ઓવરરાઇડને દૂર કરે છે.',
  "Turn this on and reps get a phone bar docked in the app — they can call or answer without a separate handset. It registers against a SIP/WebRTC line (your voice provider's SIP trunk); the settings below are what they give you for it.":
    'આને ચાલુ કરો અને પ્રતિનિધિઓને એપ્લિકેશનમાં ફોન બાર ડોક કરવામાં આવે છે — તેઓ અલગ હેન્ડસેટ વિના કૉલ કરી શકે છે અથવા જવાબ આપી શકે છે. તે SIP/WebRTC લાઇન (તમારા અવાજ પ્રદાતાની SIP ટ્રંક) સામે નોંધણી કરે છે; નીચેની સેટિંગ્સ તે છે જે તેઓ તમને તેના માટે આપે છે.',
