  'Unpaid ERP invoices': 'અવેતન ERP ઇન્વૉઇસેસ',
  'Unpaid invoices from Tally or SAP. When switched on, the customer gets your approved reminder 3 days before the due date, then at 7 and 15 days overdue. Each stage goes once; reminders stop when the ERP shows the invoice paid.':
    'Tally અથવા SAP તરફથી અવેતન ઇન્વૉઇસ. જ્યારે સ્વિચ ઓન કરવામાં આવે છે, ત્યારે ગ્રાહકને નિયત તારીખના 3 દિવસ પહેલા તમારું મંજૂર રીમાઇન્ડર મળે છે, પછી 7 અને 15 દિવસની મુદત પડતી હોય છે. દરેક તબક્કો એકવાર જાય છે; જ્યારે ERP ચૂકવેલ ઇન્વોઇસ બતાવે છે ત્યારે રીમાઇન્ડર્સ બંધ થાય છે.',
