  Wallet: 'વૉલેટ',
  'Wallet balance': 'વૉલેટ બેલેન્સ',
  'Wallet balance is running low': 'વૉલેટ બેલેન્સ ઓછું ચાલી રહ્યું છે',
  'Wallet covers the estimate': 'વૉલેટ અંદાજ આવરી લે છે',
  'Wants a quote for 3 replacement servo drives for the line installed in 2023. Asked about delivery before the plant shutdown on 18 Nov.':
    '2023 માં ઇન્સ્ટોલ કરેલી લાઇન માટે 3 રિપ્લેસમેન્ટ સર્વો ડ્રાઇવ્સ માટે ક્વોટ માંગે છે. 18 નવેમ્બરે પ્લાન્ટ બંધ થાય તે પહેલાં ડિલિવરી વિશે પૂછવામાં આવ્યું.',
  'Wants the payback sheet before Friday…': 'શુક્રવાર પહેલા પેબેક શીટ જોઈએ છે...',
  Warehouse: 'વેરહાઉસ',
  Warm: 'ગરમ',
  'Warranty & billable parts': 'વોરંટી અને બિલપાત્ર ભાગો',
  'Warranty ends': 'વોરંટી સમાપ્ત થાય છે',
  'Warranty expiry': 'વોરંટી સમાપ્તિ',
  'Wasted / Scrap Qty': 'બગાડ / ભંગાર જથ્થો',
  Watch: 'વોચ',
  'Watch from (below: at risk)': 'અહીંથી જુઓ (નીચે: જોખમમાં)',
  'Watch how it behaves, then widen the rollout.':
    'તે કેવી રીતે વર્તે છે તે જુઓ, પછી રોલઆઉટને વિસ્તૃત કરો.',
  'Watch the preview, which fills in sample values, then Save.':
    'પૂર્વાવલોકન જુઓ, જે નમૂના મૂલ્યો ભરે છે, પછી સાચવો.',
  'Watch the usage meter: amber past 60%, red past 80%.':
    'વપરાશ મીટર જુઓ: એમ્બર પાસ્ટ 60%, રેડ પાસ્ટ 80%.',
  'Water treatment': 'પાણીની સારવાર',
  'We aim to resolve every complaint within 30 days. If you are not satisfied with our response, you may escalate it to the':
    'અમે 30 દિવસની અંદર દરેક ફરિયાદનું નિરાકરણ લાવવાનું લક્ષ્ય રાખીએ છીએ. જો તમે અમારા પ્રતિભાવથી સંતુષ્ટ ન હોવ, તો તમે તેને આગળ વધારી શકો છો',
  'We can send a confirmation link to': 'અમે એક પુષ્ટિકરણ લિંક મોકલી શકીએ છીએ',
  "We can't reach MNI Assist right now.": 'અમે અત્યારે MNI આસિસ્ટ સુધી પહોંચી શકતા નથી.',
  'We could not confirm that payment. If money left your account it will be credited once the gateway confirms it.':
    'અમે તે ચુકવણીની પુષ્ટિ કરી શક્યા નથી. જો તમારા ખાતામાંથી પૈસા નીકળી ગયા હોય તો ગેટવે તેની પુષ્ટિ કરે તે પછી તે જમા કરવામાં આવશે.',
  "We couldn't change the password just now. Try again.":
    'અમે હમણાં જ પાસવર્ડ બદલી શક્યા નથી. ફરી પ્રયાસ કરો.',
  "We couldn't check the link just now. Request a new one and try again.":
    'અમે હમણાં જ લિંક તપાસી શક્યા નથી. એક નવી વિનંતી કરો અને ફરી પ્રયાસ કરો.',
  "We couldn't send that just now. Check your connection and try again.":
    'અમે તે હમણાં જ મોકલી શક્યા નથી. તમારું કનેક્શન તપાસો અને ફરી પ્રયાસ કરો.',
  "We do not sell contact data, and we do not use one tenant's contacts or message content to build profiles used for any other tenant, or for advertising.":
    'અમે સંપર્ક ડેટા વેચતા નથી, અને અમે એક ભાડૂતના સંપર્કો અથવા સંદેશ સામગ્રીનો ઉપયોગ અન્ય કોઈપણ ભાડૂત માટે અથવા જાહેરાત માટે ઉપયોગમાં લેવાતી પ્રોફાઇલ્સ બનાવવા માટે કરતા નથી.',
  "We don't track stock": 'અમે સ્ટોકને ટ્રેક કરતા નથી',
  'We email a code to confirm it is you.':
    'તે તમે જ છો તેની પુષ્ટિ કરવા માટે અમે કોડ ઈમેઈલ કરીએ છીએ.',
  'We have an update for you.': 'અમારી પાસે તમારા માટે એક અપડેટ છે.',
  'We will update the date at the top of this page when this policy changes, and for a material change, tell tenant administrators directly.':
    'જ્યારે આ નીતિ બદલાશે ત્યારે અમે આ પૃષ્ઠની ટોચ પર તારીખ અપડેટ કરીશું, અને સામગ્રીમાં ફેરફાર માટે, ભાડૂત સંચાલકોને સીધા જ જણાવો.',
  "We'll send a code to your WhatsApp. Use the number your supplier knows you by.":
    'અમે તમારા WhatsApp પર કોડ મોકલીશું. તમારા સપ્લાયર તમને ઓળખે છે તે નંબરનો ઉપયોગ કરો.',
  "We're closed for Diwali from 7 to 11 November and will reply on 12 November. For breakdowns call +91 98200 11234.":
    'અમે દિવાળી માટે 7 થી 11 નવેમ્બર સુધી બંધ છીએ અને 12 નવેમ્બરે જવાબ આપીશું. બ્રેકડાઉન માટે +91 98200 11234 પર કૉલ કરો.',
  "We're closed for a period (plant shutdown, festival week)":
    'અમે સમયગાળા માટે બંધ છીએ (પ્લાન્ટ શટડાઉન, તહેવાર સપ્તાહ)',
  'Web app and sign-in': 'વેબ એપ્લિકેશન અને સાઇન ઇન',
  'Web forms · MNI Assist': 'વેબ ફોર્મ્સ · MNI આસિસ્ટ',
  Webhook: 'વેબહૂક',
  'Webhook endpoints': 'વેબહૂક એન્ડપોઇન્ટ',
  Website: 'વેબસાઈટ',
  'Website form': 'વેબસાઇટ ફોર્મ',
  'Website form with a WhatsApp opt-in': 'WhatsApp ઑપ્ટ-ઇન સાથે વેબસાઇટ ફોર્મ',
  'Website widget snippet': 'વેબસાઇટ વિજેટ સ્નિપેટ',
