  Weighted: 'ભારિત',
  'Welcome greeting': 'સ્વાગત શુભેચ્છા',
  'Welcome message': 'સ્વાગત સંદેશ',
  'Welcome, away and out-of-office messages': 'સ્વાગત, દૂર અને ઑફિસની બહાર સંદેશાઓ',
  What: 'શું',
  "What Exotel's Say applet speaks — copy this into the matching step of the dashboard flow.":
    "Exotel's Say applet શું બોલે છે — આને ડેશબોર્ડ ફ્લોના મેચિંગ સ્ટેપમાં કૉપિ કરો.",
  'What Meta charges (₹ per message)': 'શું મેટા શુલ્ક (સંદેશ દીઠ ₹)',
  'What came of it': 'તેમાંથી શું આવ્યું',
  'What did you do?': 'તમે શું કર્યું?',
  'What did you find?': 'તમને શું મળ્યું?',
  'What do I get invoices for?': 'હું શેના માટે ઇન્વૉઇસ મેળવી શકું?',
  'What do you need?': 'તમારે શું જોઈએ છે?',
  "What each campaign brought in: delivered, read and replied, then the enquiries its recipients opened and the value won from them. An enquiry counts for a campaign when it was opened within the attribution window after the recipient's message.":
    'દરેક ઝુંબેશમાં શું આવ્યું: વિતરિત, વાંચ્યું અને જવાબ આપ્યો, પછી તેના પ્રાપ્તકર્તાઓએ પૂછપરછ કરી અને તેમની પાસેથી મૂલ્ય જીત્યું. જ્યારે પ્રાપ્તકર્તાના સંદેશા પછી એટ્રિબ્યુશન વિંડોમાં તે ખોલવામાં આવે ત્યારે ઝુંબેશ માટે પૂછપરછની ગણતરી કરવામાં આવે છે.',
  'What happened': 'શું થયું',
  'What happened? (recorded on the enquiry)': 'શું થયું? (પૂછપરછ પર નોંધાયેલ)',
  'What has to be done': 'શું કરવું પડશે',
  "What has to be done, and by when. Tick a task to finish it. A task about a deal shows on that deal's timeline once done, and you are reminded before it is due.":
    'શું કરવું જોઈએ, અને ક્યારે. કાર્ય પૂર્ણ કરવા માટે તેને ટિક કરો. સોદા વિશેનું કાર્ય એકવાર પૂર્ણ થયા પછી તે સોદાની સમયરેખા પર બતાવે છે, અને તે નિયત સમય પહેલાં તમને યાદ અપાય છે.',
  'What is affected, what to do meanwhile, when we will update next.':
    'શું અસર થાય છે, તે દરમિયાન શું કરવું, જ્યારે અમે આગળ અપડેટ કરીશું.',
  'What it does': 'તે શું કરે છે',
  "What it's for": 'તે શેના માટે છે',
  'What moves': 'શું ખસે છે',
  'What should this message say?': 'આ સંદેશને શું કહેવું જોઈએ?',
  'What tenants pay (₹ per message)': 'ભાડૂતો શું ચૂકવે છે (સંદેશ દીઠ ₹)',
  'What tenants pay per message, and when it changed. Meta announces rate changes weeks ahead, so a scheduled one appears here before it bills. Superseded rates are kept rather than overwritten — a campaign report from December has to keep costing what it cost.':
    'ભાડૂતો સંદેશ દીઠ શું ચૂકવે છે અને તે ક્યારે બદલાય છે. મેટા અઠવાડિયા આગળ દર ફેરફારોની જાહેરાત કરે છે, તેથી તે બિલ આવે તે પહેલાં શેડ્યૂલ કરેલ એક અહીં દેખાય છે. ઓવરરાઇટ કરવાને બદલે સુપરસેડ કરેલા દરો રાખવામાં આવે છે - ડિસેમ્બરના ઝુંબેશ અહેવાલમાં તેની કિંમત કેટલી છે તે રાખવાની હોય છે.',
  'What the assistant did with recent messages': 'તાજેતરના સંદેશાઓ સાથે સહાયકે શું કર્યું',
  'What the customer said, what has been tried…':
    'ગ્રાહકે શું કહ્યું, શું પ્રયાસ કરવામાં આવ્યો છે...',
  'What the merged contact gains': 'મર્જ કરેલ સંપર્કને શું ફાયદો થાય છે',
  'What the plan includes': 'યોજનામાં શું શામેલ છે',
  'What this team handles': 'આ ટીમ શું સંભાળે છે',
  'What to order now, and what will run out before the next delivery.':
    'હવે શું ઓર્ડર કરવું, અને આગામી ડિલિવરી પહેલાં શું સમાપ્ત થઈ જશે.',
  'What to sync': 'શું સમન્વયિત કરવું',
  'What to tell the customer…': 'ગ્રાહકને શું કહેવું...',
  'What was said': 'શું કહ્યું હતું',
  'What you are on course to sell in a month or quarter. Expected weights each open deal due in the period by how likely its stage is to win. Commit is what is won plus deals in Negotiation. Best case is everything scheduled landing. Deals with no close date, or a date that has passed, are listed but not counted.':
    'તમે એક મહિના અથવા ક્વાર્ટરમાં શું વેચવાના કોર્સ પર છો. સમયગાળામાં દરેક ઓપન ડીલનું અપેક્ષિત વજન તેની જીતવાની કેટલી શક્યતા છે. પ્રતિબદ્ધતા એ છે જે વત્તા વાટાઘાટમાં સોદા જીતવામાં આવે છે. શ્રેષ્ઠ કેસ બધું સુનિશ્ચિત ઉતરાણ છે. કોઈ બંધ તારીખ સાથેના સોદા, અથવા જે તારીખ પસાર થઈ ગઈ છે, તે સૂચિબદ્ધ છે પરંતુ તેની ગણતરી કરવામાં આવતી નથી.',
  'What you found, what you changed, parts used': 'તમને શું મળ્યું, તમે શું બદલ્યું, ભાગો વપરાયા',
