  'WhatsApp goes only to a customer who has agreed to be messaged, and outside the 24-hour window it needs an approved template. If something cannot be sent, you are told why and can still copy the link.':
    'વ્હોટ્સએપ ફક્ત એવા ગ્રાહકને જ જાય છે જે સંદેશ મોકલવા માટે સંમત થયા હોય, અને 24-કલાકની વિંડોની બહાર તેને માન્ય નમૂનાની જરૂર હોય છે. જો કંઈક મોકલી શકાતું નથી, તો તમને શા માટે કહેવામાં આવે છે અને હજુ પણ લિંકની નકલ કરી શકો છો.',
