  'When back online, tap Sync to push your offline updates to the office.':
    'જ્યારે પાછા ઓનલાઈન હોય, ત્યારે તમારા ઑફલાઇન અપડેટ્સને ઑફિસમાં મોકલવા માટે સિંક પર ટૅપ કરો.',
  'When it is due': 'જ્યારે તે બાકી છે',
  'When paid or ordered, mark Dispatch, In transit and Delivered as it ships.':
    'જ્યારે ચૂકવણી કરવામાં આવે અથવા ઓર્ડર આપવામાં આવે, ત્યારે ડિસ્પેચ, ટ્રાન્ઝિટમાં અને ડિલિવર્ડ તરીકે માર્ક કરો.',
  'When recording starts, the customer hears this. Without a clip of your own they hear two short beeps. Record a line such as “This call is recorded for quality and training” and upload it: audio only, up to 1 MB.':
    'જ્યારે રેકોર્ડિંગ શરૂ થાય છે, ત્યારે ગ્રાહક આ સાંભળે છે. તમારી પોતાની ક્લિપ વિના તેઓ બે ટૂંકી બીપ સાંભળે છે. "આ કૉલ ગુણવત્તા અને તાલીમ માટે રેકોર્ડ કરવામાં આવ્યો છે" જેવી લાઇન રેકોર્ડ કરો અને તેને અપલોડ કરો: ફક્ત ઑડિયો, 1 MB સુધી.',
  'When the work is done, send the customer a code on WhatsApp to confirm it.':
    'જ્યારે કામ પૂર્ણ થઈ જાય, ત્યારે ગ્રાહકને તેની પુષ્ટિ કરવા માટે WhatsApp પર એક કોડ મોકલો.',
